using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using UniHub.Application.DTOs.Perfil; using UniHub.Infrastructure.Data; namespace UniHub.API.Controllers; [ApiController] [Route("api/perfil")] [Authorize] public class PerfilController : ControllerBase { private readonly AppDbContext _context; public PerfilController(AppDbContext context) { _context = context; } [HttpGet] public async Task<ActionResult<PerfilRespostaDto>> ObterPerfil() { var usuarioId = Guid.Parse(User.FindFirst("sub")?.Value ?? Guid.Empty.ToString()); var usuario = await _context.Usuarios .Include(u => u.Vendedor) .Include(u => u.Voluntario) .FirstOrDefaultAsync(u => u.Id == usuarioId); if (usuario is null) return NotFound(new { mensagem = "Usuario nao encontrado." }); var resposta = new PerfilRespostaDto( usuario.Id, usuario.NomeCompleto, usuario.EmailInstitucional, usuario.Telefone, usuario.FotoPerfilUrl, usuario.Role.ToString(), usuario.Vendedor != null, usuario.Voluntario != null ); return Ok(resposta); } }